function valid(items){return Array.isArray(items)&&items.length<=300&&new Set(items.map(v=>v?.id)).size===items.length&&items.every(v=>{if(!v||typeof v.id!=='string'||v.id.length>100||!v.id||typeof v.name!=='string'||!v.name.trim()||v.name.length>100||typeof v.date!=='string'||!Number.isFinite(Date.parse(v.date))||!v.x)return false;return meta.every(f=>{const x=v.x[f.key];return f.options?f.options.some(o=>o[0]===x):Number.isFinite(x)&&x>=f.min&&x<=f.max;})&&(()=>{try{window.HVACDuctwork.fabrication(v.x);return true;}catch{return false;}})();});}
const size=x=>x.shape==='round'?'Ø '+F(x.a):F(x.a)+' × '+F(x.b),joint=x=>x.jointPreset!=='custom'?(meta.find(f=>f.key==='jointPreset').options.find(o=>o[0]===x.jointPreset)?.[1][en?1:0]||x.joint):((meta.find(f=>f.key==='joint').options.find(o=>o[0]===x.joint)?.[1][en?1:0]||x.joint)+' · '+F(x.jointLinearMass)+' kg/m');
function table(items,actions=false){const rows=items.map(v=>({...v,r:window.HVACDuctwork.fabrication(v.x)}));return '<div class="calc-table-scroll"><table class="calc-output-table segment-table"><thead><tr>'+[L('Tên / mã đoạn','Segment code'),L('Kích thước ngoài (mm)','Outside size (mm)'),L('Tôn / mối nối','Sheet / joint'),'L (m)',L('Số đoạn chế tạo','Fabricated sections'),L('Tôn mua (m²)','Purchased sheet (m²)'),L('Lắp đặt (kg)','Installed mass (kg)')].map(t=>'<th scope="col">'+t+'</th>').join('')+(actions?'<th>'+L('Thao tác','Actions')+'</th>':'')+'</tr></thead><tbody>'+rows.map(v=>'<tr><td>'+E(v.name)+'</td><td>'+size(v.x)+'</td><td>'+F(v.x.t)+' mm / '+E(joint(v.x))+'</td><td>'+F(v.x.length)+'</td><td>'+F(v.r.sections)+'</td><td>'+F(v.r.purchaseArea)+'</td><td>'+F(v.r.totalMass)+'</td>'+(actions?'<td><button type="button" data-fab-edit="'+E(v.id)+'">'+L('Sửa','Edit')+'</button> <button type="button" data-fab-delete="'+E(v.id)+'">'+L('Xóa','Delete')+'</button></td>':'')+'</tr>').join('')+'</tbody></table></div><p><strong>'+L('Tổng','Total')+': '+F(rows.reduce((s,v)=>s+v.x.length,0))+' m · '+F(rows.reduce((s,v)=>s+v.r.purchaseArea,0))+' m² · '+F(rows.reduce((s,v)=>s+v.r.totalMass,0))+' kg</strong></p>';}
function report(p){const a=p?.fabricationSegments;if(!valid(a)||!a.length)return '';return '<section class="project-report-tool"><h2>'+L('Danh sách chế tạo ống gió','Duct fabrication schedule')+'</h2>'+table(a)+'<p>'+L('Mỗi dòng là một đoạn/tuyến thẳng độc lập; không tự gộp mối nối giữa các dòng. Tôn mua có hao hụt, khối lượng lắp đặt không có hao hụt.','Each row is an independent straight run; joints between rows are not merged. Purchased sheet includes waste; installed mass excludes waste.')+'</p>'+a.map(v=>'<h3>'+E(v.name)+'</h3><p>'+E(v.date)+'</p><table class="calc-output-table"><tbody>'+meta.map(f=>'<tr><th>'+E(f.label[en?1:0])+'</th><td>'+E(f.options?f.options.find(o=>o[0]===v.x[f.key])?.[1][en?1:0]:F(v.x[f.key]))+' '+E(f.unit||'')+'</td></tr>').join('')+'</tbody></table>').join('')+'</section>';}
window.HVACFabricationSchedule={valid,report};if(document.body.dataset.tool!=='fabrication')return;
let editing=null,project=null;const panel=document.createElement('section');panel.id='fabrication-schedule';panel.className='panel segment-list item-schedule';panel.innerHTML='<div class="panel-title"><h2>'+L('Danh sách đoạn ống đã lưu','Saved duct segments')+'</h2><div class="report-buttons"><button type="button" data-fab-report>'+L('Xem báo cáo','View report')+'</button><button type="button" data-fab-print>'+L('Xuất PDF','Export PDF')+'</button></div></div><p class="field-help">'+L('Lưu từng đoạn vào dự án đang chọn. Nạp lại để sửa và cập nhật. Tối đa 300 đoạn; tổng vật tư được đưa vào báo cáo danh sách.','Save each segment to the selected project. Reload to edit and update. Up to 300 segments; material totals appear in the schedule report.')+'</p><div class="segment-editor"><label>'+L('Tên / mã đoạn','Segment name / code')+'<input type="text" data-fab-name maxlength="100" placeholder="'+L('VD: OG-01','e.g. D-01')+'"></label><button type="button" data-fab-save>'+L('Thêm vào danh sách','Add to schedule')+'</button><button type="button" data-fab-cancel hidden>'+L('Hủy sửa','Cancel edit')+'</button></div><p class="field-help" data-fab-message role="status"></p><div data-fab-list></div>';document.querySelector('.calc-method').before(panel);const $=s=>panel.querySelector('[data-fab-'+s+']'),current=()=>window.HVACProjects?.current(),items=()=>valid(current()?.fabricationSegments)?current().fabricationSegments:[],message=t=>$('message').textContent=t;
function refresh(){if(project!==current()?.id){editing=null;project=current()?.id;$('name').value='';message('');}const a=items();$('list').innerHTML=a.length?table(a,true):'<p class="field-help">'+L('Chọn hoặc tạo dự án, nhập thông số rồi lưu từng đoạn tại đây.','Select or create a project, calculate and save each segment here.')+'</p>';$('save').textContent=editing?L('Cập nhật đoạn','Update segment'):L('Thêm vào danh sách','Add to schedule');$('cancel').hidden=!editing;$('report').disabled=$('print').disabled=!a.length;}
function preview(print=false){if(!items().length)return;const html=window.HVACProjects.metadata()+report(current());document.getElementById('fabrication-list-dialog')?.remove();const d=document.createElement('dialog');d.id='fabrication-list-dialog';d.className='project-report-dialog';d.innerHTML='<div class="project-actions"><button type="button" data-close>'+L('Đóng','Close')+'</button><button type="button" data-print>'+L('Xuất PDF','Export PDF')+'</button></div><article>'+html+'</article>';document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();const run=()=>{document.getElementById('project-print-report')?.remove();const a=document.createElement('article');a.id='project-print-report';a.innerHTML=html;document.body.append(a);window.HVACPrint.run('project');};d.querySelector('[data-print]').onclick=run;if(print)run();else d.showModal();}
panel.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-fab-save')){if(!current()){message(L('Chọn hoặc tạo dự án phía trên để lưu đoạn.','Select or create a project above to save a segment.'));return;}if(editing&&(project!==current().id||!items().some(v=>v.id===editing))){message(L('Đoạn đang sửa đã thay đổi; hãy nạp lại.','The edited segment has changed; reload it.'));return;}const detail={};document.dispatchEvent(new CustomEvent('hvac-project-capture',{detail}));const v={id:editing||crypto.randomUUID(),name:$('name').value.trim(),date:new Date().toISOString(),x:detail.calculation?.x};if(!valid([v])){message(L('Nhập tên/mã đoạn và kiểm tra thông số hợp lệ trước khi lưu.','Enter a segment code and valid calculation inputs before saving.'));return;}if(!window.HVACProjects.saveFabricationSegments([...items().filter(a=>a.id!==v.id),v])){message(L('Không thể lưu. Kiểm tra dung lượng hoặc giới hạn 300 đoạn.','Unable to save. Check storage capacity or the 300-segment limit.'));return;}editing=null;$('name').value='';refresh();message(L('Đã lưu đoạn vào dự án.','Segment saved to project.'));}if(b.dataset.fabEdit){const v=items().find(v=>v.id===b.dataset.fabEdit);if(!v)return;editing=v.id;project=current().id;$('name').value=v.name;for(const [k,value] of Object.entries(v.x)){const input=document.getElementById('t-'+k);if(input)input.value=value;}document.getElementById('dw-group-0').open=true;document.dispatchEvent(new Event('hvac-fabrication-load'));document.getElementById('ductwork-form').scrollIntoView?.({block:'start',behavior:'smooth'});document.getElementById('ductwork-form').dispatchEvent(new Event('input',{bubbles:true}));refresh();message(L('Đã nạp đoạn. Nhấn Cập nhật đoạn để lưu thay đổi.','Segment loaded. Select Update segment to save changes.'));}if(b.hasAttribute('data-fab-cancel')){editing=null;$('name').value='';refresh();message('');}if(b.dataset.fabDelete){const id=b.dataset.fabDelete,pid=current()?.id,v=items().find(v=>v.id===id);if(!v)return;const d=document.createElement('dialog');d.className='project-trash-dialog';d.innerHTML='<h2>'+L('Xóa đoạn đã lưu?','Delete saved segment?')+'</h2><p>'+E(v.name)+'</p><div class="project-actions"><button type="button" data-cancel>'+L('Hủy','Cancel')+'</button><button type="button" data-delete>'+L('Xóa','Delete')+'</button></div>';document.body.append(d);d.querySelector('[data-cancel]').onclick=()=>{d.close();d.remove();};d.querySelector('[data-delete]').onclick=()=>{if(current()?.id===pid&&window.HVACProjects.saveFabricationSegments(items().filter(v=>v.id!==id))){if(editing===id)editing=null;refresh();}else message(L('Không thể lưu thay đổi.','Unable to save changes.'));d.close();d.remove();};d.showModal();}if(b.hasAttribute('data-fab-report'))preview();if(b.hasAttribute('data-fab-print'))preview(true);});document.addEventListener('hvac-project-ready',refresh);window.addEventListener('storage',()=>setTimeout(refresh,0));refresh();
